#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    array<ll, 10> frequency{};
    for (char c : s) {
        ++frequency[c - '0'];
    }

    ll bestCount = 0;
    string bestFirst = s;
    string bestSecond = s;

    for (int startingDigit = 1; startingDigit < 10; ++startingDigit) {
        auto firstFrequency = frequency;
        auto secondFrequency = frequency;

        int complementaryDigit = 10 - startingDigit;
        if (firstFrequency[startingDigit] == 0 ||
            secondFrequency[complementaryDigit] == 0) {
            continue;
        }

        string first(1, char('0' + startingDigit));
        string second(1, char('0' + complementaryDigit));

        --firstFrequency[startingDigit];
        --secondFrequency[complementaryDigit];

        ll count = 1;

        for (int digit = 0; digit < 10; ++digit) {
            int complement = 9 - digit;
            ll matches = min(firstFrequency[digit],
                             secondFrequency[complement]);

            first = string(static_cast<size_t>(matches),
                           char('0' + digit)) + first;
            second = string(static_cast<size_t>(matches),
                            char('0' + complement)) + second;

            firstFrequency[digit] -= matches;
            secondFrequency[complement] -= matches;
            count += matches;
        }

        ll zeros = min(firstFrequency[0], secondFrequency[0]);
        firstFrequency[0] -= zeros;
        secondFrequency[0] -= zeros;

        first += string(static_cast<size_t>(zeros), '0');
        second += string(static_cast<size_t>(zeros), '0');
        count += zeros;

        if (count > bestCount) {
            bestCount = count;

            for (int digit = 0; digit < 10; ++digit) {
                first = string(static_cast<size_t>(firstFrequency[digit]),
                               char('0' + digit)) + first;
                second = string(static_cast<size_t>(secondFrequency[digit]),
                                char('0' + digit)) + second;
            }

            bestFirst = move(first);
            bestSecond = move(second);
        }
    }

    cout << bestFirst << '\n' << bestSecond;
    return 0;
}

