#include <bits/stdc++.h>
using namespace std;

using ll = long long;

void solve() {
    string s;
    cin >> s;

    array<ll, 10> frequency{};
    for (char c : s) {
        ++frequency[c - '0'];
    }

    ll bestCount = -1;
    string answer1, answer2;

    for (int firstDigit = 1; firstDigit <= 9; ++firstDigit) {
        int secondDigit = 10 - firstDigit;

        if (frequency[firstDigit] == 0 || frequency[secondDigit] == 0) {
            continue;
        }

        auto remaining1 = frequency;
        auto remaining2 = frequency;

        string result1(1, char('0' + firstDigit));
        string result2(1, char('0' + secondDigit));

        --remaining1[firstDigit];
        --remaining2[secondDigit];

        ll count = 1;

        for (int digit = 0; digit <= 9; ++digit) {
            int complement = 9 - digit;
            ll pairs = min(remaining1[digit], remaining2[complement]);

            result1 = string(static_cast<size_t>(pairs), char('0' + digit)) + result1;
            result2 = string(static_cast<size_t>(pairs), char('0' + complement)) + result2;

            remaining1[digit] -= pairs;
            remaining2[complement] -= pairs;
            count += pairs;
        }

        ll zeroPairs = min(remaining1[0], remaining2[0]);
        result1 += string(static_cast<size_t>(zeroPairs), '0');
        result2 += string(static_cast<size_t>(zeroPairs), '0');
        remaining1[0] -= zeroPairs;
        remaining2[0] -= zeroPairs;
        count += zeroPairs;

        if (count > bestCount) {
            bestCount = count;

            for (int digit = 0; digit <= 9; ++digit) {
                result1 = string(static_cast<size_t>(remaining1[digit]),
                                 char('0' + digit)) + result1;
                result2 = string(static_cast<size_t>(remaining2[digit]),
                                 char('0' + digit)) + result2;
            }

            answer1 = std::move(result1);
            answer2 = std::move(result2);
        }
    }

    if (bestCount == -1) {
        answer1 = s;
        answer2 = s;
    }

    cout << answer1 << '\n' << answer2 << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}

